C = dict(id='GL-12', title='DDoS and Cyber-Attack Prevention', group='Digital and Technology', level=5,
 summary='Protect a small online service from flood attacks and common cyber attacks with layered, low-cost controls, a drill and a response plan.',
 outcomes=['Explain how flood and other common attacks work and who is hurt.', 'Apply basic hardening: updates, strong sign-in, limits on requests per visitor, and backups.', 'Analyse traffic logs to spot unusual spikes.', 'Create a response plan and run a table-top drill.', 'Evaluate your protection with a checklist and a measured test on your own system.'],
 task='Harden one small online service, set up monitoring and alerts, and run a drill of a simulated flood with a written response plan.',
 cond='A small service you own or a lab copy, free monitoring tools, access logs, a spreadsheet, a mentor with security experience and a peer circle. About 10 weeks part-time.',
 std='Only systems you own are tested; all critical updates applied; two-step sign-in on admin accounts; alert fires within 5 minutes in the drill; restore from backup proven; response plan names owners and phone contacts.',
 who='IT support, site owners, junior security staff, college learners.', req='Basic networking and computer skills.',
 safety='Test only systems you own or have written permission to test. Never attack other systems. Never run flood tools against anyone else\'s service.',
 mods=[
 ('How attacks happen', 'Know the main attack families.', ['Flood (distributed denial of service): many requests exhaust a service.', 'Phishing: tricking people into giving access.', 'Weak or reused passwords; unpatched software.', 'Ransomware: files locked until payment; backups are the cure.'], 'A shop site slows at 9 pm. Logs show 40,000 requests a minute from many places against 300 normal: flood suspected.', 'Match five attacks to the controls that reduce them.', 'List five matches with reasons.'),
 ('Know your system', 'You protect what you can list.', ['Draw the path: user, name lookup, edge, server, database.', 'List admin accounts and who holds them.', 'Mark single points of failure.', 'Note normal traffic by hour.'], 'Normal evening traffic is 300 requests a minute; set the alert at 1,500.', 'Draw the path and write the normal traffic table.', 'Mark single points; record normal numbers.'),
 ('Basic hardening', 'Most harm is stopped by dull jobs done on time.', ['Apply updates; remove unused services.', 'Strong passwords plus a second step on all admin accounts.', 'Least access: give only what a role needs.', 'Close unused ports.'], '12 admin accounts, 3 with no second step: fix all 3, count becomes 0 gaps.', 'Run a hardening checklist and fix the gaps.', 'Complete the checklist; fix gaps with dates.'),
 ('Layers against floods', 'No single tool stops a flood; layers share the load.', ['Use a filtering and caching front service.', 'Set rate limits per visitor.', 'Keep spare capacity and the ability to scale.', 'Talk to your host before an incident, not during.'], 'Caching serves 80% of pages without touching the server: 40,000 requests become 8,000 reaching the origin.', 'Set a rate limit and a cache rule on your lab service.', 'Test the rule with a safe load.'),
 ('Monitoring and alerts', 'You cannot respond to what you cannot see.', ['Collect access logs and error counts.', 'Alert on spikes, failed sign-ins and new admin accounts.', 'Send alerts to two people.', 'Review weekly.'], 'Failed sign-ins jump from 5 to 400 in ten minutes: alert triggers a password reset for the targeted account.', 'Set three alerts and test each.', 'Check that each alert fires in under 5 minutes.'),
 ('Backups and recovery', 'The last defence is a good backup.', ['Three copies, two kinds of storage, one away from the site.', 'Test a restore on a schedule.', 'Record time to restore.', 'Protect backups from deletion.'], 'Restore of 50 GB takes 3 hours; the business can accept 4 hours: pass. If it could accept 2, change the plan.', 'Restore a backup and time it.', 'Restore time recorded and compared to target.'),
 ('Incident response plan', 'In an incident people forget; paper remembers.', ['Roles: lead, technical, communicator.', 'Steps: detect, contain, fix, tell, learn.', 'Contact list: host, support, legal help.', 'Decide who may shut the service and when.'], 'At minute 10 the lead decides to switch to a static page; communicator posts a notice at minute 20.', 'Write a one-page plan.', 'Name every role, step and contact.'),
 ('Drill and review', 'A drill turns a plan into habit.', ['Run a table-top drill: read a scenario and act it out.', 'Time each step.', 'Write three fixes with dates.', 'Share lessons with the team.'], 'Drill shows nobody had the host\'s phone number: fix recorded and checked next week.', 'Run the drill and write the report.', 'List three fixes with owners and dates.')],
 quiz=[('What is a flood attack?', 'Many requests that use up a service\'s capacity.'), ('Why use a second sign-in step?', 'A stolen password alone then fails.'), ('What is least access?', 'Giving each role only what it needs.'), ('Why cache?', 'It serves pages without hitting the main server.'), ('What is the 3-2-1 backup idea?', 'Three copies, two kinds of storage, one away.'), ('Why test a restore?', 'An untested backup may not work.'), ('Name the five incident steps.', 'Detect, contain, fix, tell, learn.'), ('Whom may you test?', 'Only systems you own or have written permission for.'), ('Why alert two people?', 'One may be away.'), ('What is a table-top drill?', 'Acting out a scenario on paper to test the plan.')],
 rubric=[('Safe practice', 'Own system only; permission noted', 'Scope document signed by owner'), ('Hardening', 'Checklist complete', 'Gaps fixed and rechecked'), ('Monitoring', 'Three alerts working', 'Alerts tuned to cut false alarms'), ('Recovery', 'Restore proven and timed', 'Time meets target'), ('Response plan', 'Roles, steps, contacts', 'Drill fixes closed on time')],
 jobs=[('Security operations assistant', 'Watches alerts and logs'), ('IT support engineer', 'Hardens and patches systems'), ('Junior incident responder', 'Follows plans in attacks'), ('Website administrator', 'Keeps small sites safe')],
 next='Privacy Protection Practice; Cloud Migration as a Service; IT Service and Support.',
 local='Laws on computer misuse and breach reporting differ by country: know your reporting duty and deadline.',
 evidence='Your evidence: system map, normal-traffic table, hardening checklist, alert tests, restore log, response plan and drill report.',
 ladder=[('Basics of safe use', 'Use strong, different passwords, install updates and explain why each protects an account. Notes: set up a password manager and change three passwords in front of a mentor. Standard: no reused passwords and automatic updates on.'), ('Awareness', 'Spot phishing messages and scams by sender, link and urgency, and say what to do next. Notes: run a spot-the-scam quiz with ten real-looking messages and mark them. Standard: eight of ten right, and the right action named for each wrong one.'), ('Foundation', 'Harden one set of accounts with a second sign-in step, recovery options and a list of connected apps. Notes: second step everywhere it is offered, and a note of what you removed. Standard: every account on the list passes a five-point check.'), ('Practitioner', 'Monitor one small service with logs and alerts, and tell normal traffic from an odd spike. Notes: set an alert on a practice site, then cause a harmless spike and record the alert time. Standard: alert within five minutes and the log shows the cause.'), ('Specialist', 'Harden a small online service, set monitoring and alerts, and run a drill of a simulated flood with a written response plan. Notes: the plan names who calls whom, what is filtered first and how users are told. Standard: drill timings recorded, recovery step tested, plan updated after the drill.'), ('Advanced', 'Run a team through an attack drill and an audit, with testing done only by written permission. Notes: add a scope letter, a test plan and a report with ranked fixes. Standard: every test is inside the signed scope, and fixes have owners and dates.'), ('Super expert', 'Set the attack-response standard (detect, filter, escalate, report) and teach the teams who run it. Notes: review every incident each year and update the runbook and contact list.')])

C['deep'] = dict(mods=[
 ('Thinking attacks only hit big firms.', 'A small shop is flooded by a rival\'s bought attack and loses a weekend of orders.', 'Which attack worries you most and why?'),
 ('Not knowing normal traffic, so a spike cannot be seen.', 'Normal 300 per minute; alert at 1,500. Without that baseline the first sign is a phone call.', 'What is your normal peak?'),
 ('Leaving default passwords on routers.', 'Default admin password changed on all three devices; log kept.', 'List devices with default settings changed.'),
 ('Relying on one tool.', 'Caching removes 80% of load, rate limits stop one visitor from taking all.', 'Which layers do you have?'),
 ('Alerts that nobody reads.', 'Alert goes to two phones; one acknowledges within 5 minutes in the test.', 'Who gets each alert?'),
 ('Backups on the same server.', 'A copy is stored away from the site; the restore test uses it.', 'Where is your off-site copy?'),
 ('A plan nobody can find.', 'Plan printed and stored in a shared folder with the host\'s phone number.', 'Where is your plan?'),
 ('Drills that skip communication.', 'The drill adds a customer notice at minute 20.', 'What is your first public message?')],
 gloss=[('DDoS', 'Distributed denial of service: many sources flood a service.'), ('Rate limit', 'A cap on requests per visitor.'), ('Cache', 'Saved copies that avoid hitting the main server.'), ('Second step', 'Extra sign-in proof beyond a password.'), ('Hardening', 'Removing weaknesses.'), ('Table-top drill', 'Rehearsing a plan on paper.')],
 cases=[('The evening spike', 'Traffic jumps tenfold at 8 pm; the site is slow.', 'First three actions?', 'Confirm with logs, enable stricter filtering with the front service, tell your host, and post a notice.'),
        ('The reused password', 'An admin password leaks from another site.', 'What do you do?', 'Reset it, force a second step, check logs for use, and review other accounts.')])
C['deep']['extra'] = [
 ['Read your host\'s abuse policy and know how to report an attack to them.', 'Learn how to tell a real surge in customers from an attack, using referrer and geography.'],
 ['List external services you rely on, such as payment or email, because their outage is yours too.', 'Record the owner of each domain and certificate expiry dates.'],
 ['Turn on automatic updates where safe and schedule a monthly check.', 'Use a password manager to avoid reuse.'],
 ['Know the limits of your hosting plan, such as requests per second.', 'Prepare a light "static" page to serve during an attack.'],
 ['Create a status page for customers on a different provider from your site.', 'Review the alert list monthly and remove noisy ones.'],
 ['Encrypt backups and keep keys away from the backup location.', 'Test a restore of one file and of the full system.'],
 ['Print the plan and keep a copy off the network.', 'Agree who may speak to the press and customers.'],
 ['Run a second drill with a different scenario, such as stolen credentials.', 'Record every fix and check it six weeks later.']]
_np = [['Learn the main types: floods that overwhelm a service, stolen or guessed passwords, malicious attachments, and unpatched software, and note one real-world sign of each.', 'Remember that attackers often use automated scans on every address they can find, so a small site is probed within hours of going online.'], ['List every public service, such as website, email, remote access and any device with an address, and note its owner and software version.', 'Mark each item as critical, important or minor by asking how many hours of downtime the business can accept, and defend the critical ones first.'], ['Apply security updates promptly with critical fixes first. Set your own deadlines in writing, check any rule that applies to you, and keep a short log of what was patched and when.', 'Turn on multi-step sign-in for all admin and email accounts, remove unused accounts, and require long passwords, with a minimum length set by your own policy and the current guidance you must follow.'], ['Place a filtering service in front of public sites, set rate limits such as 100 requests per minute per address, and keep a plan to switch to a static page under load.', 'Ask your provider what protection is included, what the traffic limit is and how to contact them quickly, and save the answers where the team can find them.'], ['Set alerts on a handful of signals, such as response time over 3 seconds, error rate above 5 percent and failed logins above 20 per hour.', 'Send alerts to two named people by message and email, and review the alert list every week; an alert nobody reads is the same as having none.'], ['Follow the 3-2-1 rule: three copies, on two kinds of storage, with one kept offline or in a separate account, and write down the schedule.', 'Test a restore every quarter and record the time it took; set a recovery goal, for example back in four hours, and see if you meet it.'], ['Write a one-page plan with who decides, who calls the provider, who tells customers and the first five steps to contain the problem.', 'Keep a printed contact list, because email may be down, and note decision limits such as who may take a service offline.'], ['Run a 60-minute tabletop drill twice a year with a made-up scenario, such as a flood at 2 a.m., and note every step that was unclear.', 'After each drill write three changes with owners and dates, and update the plan within two weeks while the lessons are fresh.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
C['intro_add'] = ["You will tell flood, password, attachment and unpatched-software attacks apart by their signs, so you know which defence applies to which threat.", "You will list every public-facing service with an owner and rank it by tolerable downtime, so your protection effort goes to the critical items.", "You will apply a patching routine, multi-step sign-in and account clean-up, which together block a large share of common attacks.", "You will combine filtering, rate limits and a fallback page with provider support details, so a traffic flood is shared across layers.", "You will set a few meaningful alerts routed to named people and review them weekly, so trouble is noticed while it is still small.", "You will apply the 3-2-1 backup rule and time a real restore, proving you can recover within a goal you have set.", "You will write a one-page response plan with roles, first steps and a printed contact list, so people act in order under stress.", "You will run a timed tabletop drill and record fixes with owners and dates, turning the written plan into a practised habit."]
